Una pizzería quiere saber qué combinaciones de ingredientes suman un número de calorías exacto.

function combosCalorias(calorias, total) {
  const res = [];
  const actual = [];
  function probar(i, suma) {
    if (i === calorias.length) {
      if (suma === total) res.push([...actual]);
      return;
    }
    actual.push(calorias[i]);
    probar(i + 1, suma + calorias[i]);
    actual.pop();
    probar(i + 1, suma);
  }
  probar(0, 0);
  return res;
}
